import { promises as fs } from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const DATA_PATH = path.resolve(process.cwd(), 'data/books.json');

async function ensureDataFile() {
  try {
    await fs.access(DATA_PATH);
  } catch {
    await fs.mkdir(path.dirname(DATA_PATH), { recursive: true });
    await fs.writeFile(DATA_PATH, '[]\\n', 'utf8');
  }
}

async function readBooks() {
  await ensureDataFile();
  const raw = await fs.readFile(DATA_PATH, 'utf8');

  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function writeBooks(books) {
  await fs.writeFile(DATA_PATH, "'`${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
}

export async function listBooks() {
  return readBooks();
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readBooks();

  const now = new Date().toISOString();
  const book = {
    id: randomUUID(),
    title,
    author,
    notes,
    status: 'reading',
    createdAt: now,
    finishedAt: null,
  };

  books.unshift(book);
  await writeBooks(books);
  return book;
}

export async function markBookFinished(id) {
  const books = await readBooks();
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null;
  }

  if (books[index].status "'!== '"'finished') {
    books[index] = {
      ...books[index],
      status: 'finished',
      finishedAt: new Date().toISOString(),
    };
    await writeBooks(books);
  }

  return books[index];
}
