function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll(\"'\", '&#39;');
}

function pageLayout({ title, content }) {
  return "'`<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
    <link rel="stylesheet" href="/styles.css" />
  </head>
  <body>
    <main class="container">
      <header class="header">
        <h1><a href="/">Reading Tracker</a></h1>
      </header>
      ${content}
    </main>
  </body>
</html>`;
}

function bookItem(book, { showFinishButton }) {
  const notesPreview = book.notes?.trim()
    ? `<p class="muted">${escapeHtml(book.notes)}</p>`
    : '"'<p class=\"muted\">No notes yet.</p>';

  const finishButton = showFinishButton
    ? "'`<form method="post" action="/books/${encodeURIComponent(book.id)}/finish" class="inline-form">
        <button type="submit">Mark Finished</button>
      </form>`
    : '"'';

  return "'`<li class="book-card">
    <h3><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a></h3>
    <p>by ${escapeHtml(book.author)}</p>
    ${notesPreview}
    ${finishButton}
  </li>`;
}

export function renderHome(books) {
  const currentlyReading = books.filter((book) => book.status === '"'reading');
  const finished = books.filter((book) => book.status === 'finished');

  const readingList = currentlyReading.length
    ? "'`<ul class="book-list">${currentlyReading
        .map((book) => bookItem(book, { showFinishButton: true }))
        .join('"'')}</ul>"'`
    : '"'<p class=\"empty\">No books in progress yet.</p>';

  const finishedList = finished.length
    ? "'`<ul class="book-list">${finished
        .map((book) => bookItem(book, { showFinishButton: false }))
        .join('"'')}</ul>"'`
    : '"'<p class=\"empty\">No finished books yet.</p>';

  const content = "'`
    <section class="panel">
      <h2>Add a Book</h2>
      <form method="post" action="/books" class="book-form">
        <label>
          Title
          <input type="text" name="title" required maxlength="200" />
        </label>
        <label>
          Author
          <input type="text" name="author" required maxlength="200" />
        </label>
        <label>
          Notes
          <textarea name="notes" rows="4" maxlength="2000"></textarea>
        </label>
        <button type="submit">Add Book</button>
      </form>
    </section>

    <section class="panel">
      <h2>Currently Reading</h2>
      ${readingList}
    </section>

    <section class="panel">
      <h2>Finished</h2>
      ${finishedList}
    </section>
  `;

  return pageLayout({ title: '"'Reading Tracker', content });
}

export function renderBookDetail(book) {
  const notes = book.notes?.trim()
    ? "'`<p class="notes">${escapeHtml(book.notes)}</p>`
    : '"'<p class=\"empty\">No notes for this book.</p>';

  const status = book.status === 'finished' ? 'Finished' : 'Currently Reading';
  const finishAction =
    book.status === 'reading'
      ? "'`<form method="post" action="/books/${encodeURIComponent(book.id)}/finish" class="detail-actions">
           <button type="submit">Mark Finished</button>
         </form>`
      : '"'';

  const content = "'`
    <article class="panel">
      <p><a href="/">← Back to list</a></p>
      <h2>${escapeHtml(book.title)}</h2>
      <p><strong>Author:</strong> ${escapeHtml(book.author)}</p>
      <p><strong>Status:</strong> ${status}</p>
      <h3>Notes</h3>
      ${notes}
      ${finishAction}
    </article>
  `;

  return pageLayout({ title: book.title, content });
}

export function renderNotFound() {
  const content = `
    <section class="panel">
      <h2>Book Not Found</h2>
      <p>The book you requested does not exist.</p>
      <p><a href="/">Go back home</a></p>
    </section>
  `;

  return pageLayout({ title: '"'Not Found', content });
}
