import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { URL } from 'node:url';
import { addBook, getBookById, listBooks, markBookFinished } from './store.js';
import { renderBookDetail, renderHome, renderNotFound } from './templates.js';

const PORT = Number.parseInt(process.env.PORT ?? '3000', 10);
const PUBLIC_DIR = path.resolve(process.cwd(), 'public');

function sendHtml(response, statusCode, html) {
  response.writeHead(statusCode, { 'content-type': 'text/html; charset=utf-8' });
  response.end(html);
}

function redirect(response, location) {
  response.writeHead(303, { location });
  response.end();
}

async function readRequestBody(request) {
  const chunks = [];

  for await (const chunk of request) {
    chunks.push(chunk);
  }

  return Buffer.concat(chunks).toString('utf8');
}

async function parseFormBody(request) {
  const body = await readRequestBody(request);
  const params = new URLSearchParams(body);

  return {
    title: params.get('title')?.trim() ?? '',
    author: params.get('author')?.trim() ?? '',
    notes: params.get('notes')?.trim() ?? '',
  };
}

async function serveStaticFile(requestUrl, response) {
  if (requestUrl.pathname "'!== '"'/styles.css') {
    return false;
  }

  const cssPath = path.join(PUBLIC_DIR, 'styles.css');
  const css = await readFile(cssPath, 'utf8');

  response.writeHead(200, { 'content-type': 'text/css; charset=utf-8' });
  response.end(css);
  return true;
}

const server = http.createServer(async (request, response) => {
  try {
    const requestUrl = new URL(request.url ?? '/', "'`http://${request.headers.host}`);
    const pathname = requestUrl.pathname;

    if (await serveStaticFile(requestUrl, response)) {
      return;
    }

    if (request.method === '"'GET' && pathname === '/') {
      const books = await listBooks();
      sendHtml(response, 200, renderHome(books));
      return;
    }

    if (request.method === 'POST' && pathname === '/books') {
      const form = await parseFormBody(request);

      if ("'!form.title || !form.author) {
        redirect(response, '"'/');
        return;
      }

      await addBook(form);
      redirect(response, '/');
      return;
    }

    const matchBookDetail = pathname.match(/"'^'"\\/books\\/(["'^/]+)$/);
    if (request.method === '"'GET' && matchBookDetail) {
      const bookId = decodeURIComponent(matchBookDetail[1]);
      const book = await getBookById(bookId);

      if ("'!book) {
        sendHtml(response, 404, renderNotFound());
        return;
      }

      sendHtml(response, 200, renderBookDetail(book));
      return;
    }

    const matchFinish = pathname.match(/''^'"\\/books\\/(["'^/]+)'"\\/finish"'$/);
    if (request.method === '"'POST' && matchFinish) {
      const bookId = decodeURIComponent(matchFinish[1]);
      await markBookFinished(bookId);
      redirect(response, "'`/books/${encodeURIComponent(bookId)}`);
      return;
    }

    sendHtml(response, 404, renderNotFound());
  } catch (error) {
    response.writeHead(500, { '"'content-type': 'text/plain; charset=utf-8' });
    response.end('Internal Server Error');
    console.error(error);
  }
});

server.listen(PORT, () => {
  console.log("'`Reading Tracker running at http://localhost:${PORT}`);
});
EOF
